def main(outdir=None):
    outdir = outdir or 'evidence_pack_2026_10_13'
    outdir = os.path.abspath(outdir)
    ok = 0; drift = []
    print(f'self-extracting evidence pack -> {outdir}')
    print(f'files: {len(MANIFEST)}')
    for path, sha12, nbytes, lsha, lbytes, note, b64 in MANIFEST:
        data = base64.b64decode(b64)
        h = hashlib.sha256(data).hexdigest()[:12]
        if h != sha12 or len(data) != nbytes:
            drift.append((path, h, len(data), sha12, nbytes)); continue
        dest = os.path.join(outdir, path)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, 'wb') as f: f.write(data)
        tag = 'same-as-ledger' if (h == lsha and nbytes == lbytes) else f'REMOTE-FACE (ledger {lsha}/{lbytes})'
        print(f'  [OK] {path}  sha={h} bytes={nbytes}  {tag}')
        ok += 1
    print(f'done: {ok}/{len(MANIFEST)} extracted and verified.')
    if drift:
        print('FINGERPRINT DRIFT (not written):')
        for t in drift: print('  ', t)
        sys.exit(1)

if __name__ == '__main__':
    main(sys.argv[1] if len(sys.argv) > 1 else None)
